# Writes the hedra command files of the air hockey arcade's room and game pieces: floor.txt (the
# carpet, with textures/carpet.png drawn here), cabinet.txt, stool.txt, plant.txt, mallet_p.txt
# (the player's), mallet_c.txt (the computer's), puck.txt, spark.txt. Run from models/env:
# /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); colours exact SLSO-CLR17. World (glTF) = (x, z, -y) of hedra.
import random
from PIL import Image

HEX = {"ink": "2e2c3b", "slate": "3e415f", "steel": "55607d", "grey": "747d88", "mint": "41de95",
       "teal": "2aa4aa", "blue": "3b77a6", "dgreen": "249337", "green": "56be44", "lime": "c6de78",
       "yellow": "f3c220", "orange": "c4651c", "red": "b54131", "plum": "61407a", "purple": "8f3da7",
       "pink": "ea619d", "ice": "c1e5ea"}


def rgb(n):
    h = HEX[n]
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def col(n):
    r, g, b = (c / 255 for c in rgb(n))
    return f"--base-color {r:.4f} {g:.4f} {b:.4f}"


files = {}

# ---------------------------------------------------------------- carpet texture (an arcade carpet)
# 9 x 6.5 m of floor at 0.0625 m a texel: 144 x 104. Base slate, plum confetti shapes (diamonds,
# zigzags, rings) 3 to 5 texels: big enough to survive the splats (about 2 splats a shape).
TW, TH = 144, 104
img = Image.new("RGB", (TW, TH), rgb("slate"))
px = img.load()
rnd = random.Random(11)
def put(x, y, c):
    px[x % TW, y % TH] = rgb(c)
for i in range(150):
    x, y = rnd.randrange(TW), rnd.randrange(TH)
    kind = rnd.randrange(3)
    if kind == 0:      # a diamond
        for dy in range(-2, 3):
            for dx in range(-2 + abs(dy), 3 - abs(dy)):
                put(x + dx, y + dy, "plum")
    elif kind == 1:    # a zigzag, two texels thick
        for k in range(6):
            yy = y + (k % 2)
            put(x + k, yy, "plum"); put(x + k, yy + 1, "plum")
    else:              # a ring 5 x 5
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                if abs(dx) == 2 or abs(dy) == 2:
                    if not (abs(dx) == 2 and abs(dy) == 2):
                        put(x + dx, y + dy, "plum")
import os
os.makedirs("textures", exist_ok=True)
img.save("textures/carpet.png")

files["floor"] = f"""# Floor: the arcade's carpet, 9 x 6.5 m, top at z 0 (the world's y -0.82 under the table), a slate
# carpet with plum confetti (textures/carpet.png, drawn by make_env.py) projected from the top.
# Generated by make_env.py. Up Z, front -Y.
new
material new Carpet --base-color 1 1 1 --no-slot
material texture Carpet base-color textures/carpet.png
add mesh cube --name Floor --size 1 --location 0 0.75 -0.1
scale 9 6.5 0.2
apply --scale
material assign Carpet
mode edit
select face where "normal.z < 0.9"
delete only-faces
select all
uv project-from-view top --scale-to-bounds
mode object
shade flat
export floor.glb
"""

# ---------------------------------------------------------------- arcade cabinet
# 0.8 wide, 0.72 deep, 1.75 tall, facing -Y: a body, a screen recess tilted back with a glowing
# screen, a control ledge with two buttons, a glowing marquee on top.
files["cabinet"] = f"""# Arcade cabinet: a slate body, a tilted glowing screen, a control ledge with two buttons and a
# glowing marquee. Generated by make_env.py. Up Z, front -Y, origin on the floor under the centre.
new
material new Body {col('slate')} --no-slot
material new Screen {col('teal')} --no-slot
material new Marquee {col('pink')} --no-slot
material new Button {col('yellow')} --no-slot
add mesh cube --name Body --size 1 --location 0 0.05 0.875
scale 0.8 0.62 1.75
apply --scale
material assign Body
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
add mesh cube --name Ledge --size 1 --location 0 -0.36 0.92
scale 0.8 0.32 0.12
apply --scale
material assign Body
add mesh cube --name Screen --size 1 --location 0 -0.27 1.3
scale 0.6 0.06 0.46
apply --scale
set rotation -14 0 0
apply --rotation
material assign Screen
add mesh cube --name Marquee --size 1 --location 0 -0.29 1.66
scale 0.8 0.08 0.2
apply --scale
material assign Marquee
add mesh cylinder --name B1 --vertices 6 --radius 0.06 --depth 0.06 --location -0.15 -0.4 1.0
material assign Button
add mesh cylinder --name B2 --vertices 6 --radius 0.06 --depth 0.06 --location 0.15 -0.4 1.0
material assign Button
select Body Ledge Screen Marquee B1 B2
active Body
join
shade flat
export cabinet.glb
"""

# ---------------------------------------------------------------- bar stool
files["stool"] = f"""# Bar stool: a red round seat on a steel post and foot. Generated by make_env.py. Up Z.
new
material new Seat {col('red')} --no-slot
material new Post {col('steel')} --no-slot
add mesh cylinder --name Seat --vertices 10 --radius 0.24 --depth 0.12 --location 0 0 0.7
material assign Seat
add mesh cylinder --name Pole --vertices 6 --radius 0.055 --depth 0.62 --location 0 0 0.33
material assign Post
add mesh cylinder --name Foot --vertices 10 --radius 0.22 --depth 0.05 --location 0 0 0.025
material assign Post
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
select Seat Pole Foot
active Seat
join
shade flat
export stool.glb
"""

# ---------------------------------------------------------------- potted plant
files["plant"] = f"""# Potted plant: a slate pot and three faceted lumps of leaves. Generated by make_env.py. Up Z.
new
material new Pot {col('steel')} --no-slot
material new Leaf {col('green')} --no-slot
add mesh cone --name Pot --vertices 8 --radius1 0.22 --radius2 0.3 --depth 0.45 --location 0 0 0.225
material assign Pot
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
add mesh ico-sphere --name L0 --subdivisions 1 --radius 0.38 --location 0 0 0.78
add mesh ico-sphere --name L1 --subdivisions 1 --radius 0.3 --location 0.22 -0.1 1.12
add mesh ico-sphere --name L2 --subdivisions 1 --radius 0.27 --location -0.2 0.08 1.2
select L0 L1 L2
active L0
join
material assign Leaf
mode edit
select all
randomize --amount 0.05 --seed 4
mode object
select Pot L0
active Pot
join
shade flat
export plant.glb
"""

# ---------------------------------------------------------------- mallets (one per side's colours)
def mallet(name, body, knob, note):
    return f"""# Mallet ({note}): a wide disc with a raised rim, a short handle and a ball knob, 0.44 across,
# 0.32 tall; origin at the bottom centre (the game slides it on the playing surface).
# Generated by make_env.py. Up Z.
new
material new Body {col(body)} --no-slot
material new Knob {col(knob)} --no-slot
add mesh cylinder --name Disc --vertices 12 --radius 0.22 --depth 0.08 --location 0 0 0.04
material assign Body
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
inset 0.06
translate 0 0 -0.03
mode object
add mesh cylinder --name Handle --vertices 8 --radius 0.075 --depth 0.16 --location 0 0 0.13
material assign Body
add mesh ico-sphere --name Ball --subdivisions 1 --radius 0.105 --location 0 0 0.23
material assign Knob
select Disc Handle Ball
active Disc
join
shade flat
export {name}.glb
"""
files["mallet_p"] = mallet("mallet_p", "orange", "yellow", "the player's, orange")
files["mallet_c"] = mallet("mallet_c", "purple", "pink", "the computer's, purple")

# ---------------------------------------------------------------- puck
files["puck"] = f"""# Puck: a flat glowing disc 0.28 across, 0.06 thick; origin at the bottom centre.
# Generated by make_env.py. Up Z.
new
material new Puck {col('yellow')} --no-slot
add mesh cylinder --name Puck --vertices 10 --radius 0.14 --depth 0.06 --location 0 0 0.03
material assign Puck
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
shade flat
export puck.glb
"""

# ---------------------------------------------------------------- spark (a pooled particle)
files["spark"] = f"""# Spark: a tiny diamond (an octahedron-like ico), 0.08 across. Generated by make_env.py. Up Z.
new
material new Spark {col('yellow')} --no-slot
add mesh ico-sphere --name Spark --subdivisions 1 --radius 0.045 --location 0 0 0
material assign Spark
shade flat
export spark.glb
"""

for k, v in files.items():
    with open(f"{k}.txt", "w") as f:
        f.write(v)
print("wrote", " ".join(f"{k}.txt" for k in files), "and textures/carpet.png")
